[GUPPricingMetadataDiscovery][GUPPricingAttributeSourceDiscovery(GUPPricingAttributeSource::CustomerPriceGroup, GUPPricingAttributeSourceLevel::Header)]
[GUPPricingAttributeFieldsDiscovery(fieldStr(GUPPricingAttributeGroup, Name))]
internal class GUPPricingAttributeCustomerPriceGroup extends GUPPricingAttributePriceGroup implements GUPIPricingAttribute
{

}

Method.Source:
    public Set getAllowedValues()
    {
        var valueSet = new Set(Types::String);

        GUPPricingAttributeGroup gupPricingAttributeGroup;

        while select gupPricingAttributeGroup
            where gupPricingAttributeGroup.GroupType == GUPPricingAttributeGroupType::Customer   
            && gupPricingAttributeGroup.IsValid == NoYes::Yes
        {
            valueSet.add(gupPricingAttributeGroup.Name);
        }

        return valueSet;
    }

    public void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
    {
        QueryBuildRange qbr;

        qbr = _qbds.addRange(fieldNum(CustTable, CustGroup));
        qbr.value(queryValue(_value));
    }
